const fs = require("fs");
const path = require("path");
const cp = require("child_process");
const dir = "/w/workerid";
fs.rmSync(dir, { recursive: true, force: true });
fs.mkdirSync(dir, { recursive: true });
function write(file, text) {
  fs.writeFileSync(path.join(dir, file), text);
}
function vitest(args) {
  const r = cp.spawnSync(process.execPath, ["/w/node_modules/vitest/vitest.mjs", ...args], {
    cwd: dir,
    encoding: "utf8",
    env: { ...process.env, NO_COLOR: "1", CI: "1" },
    timeout: 60000,
  });
  return { status: r.status, out: (r.stdout || "") + (r.stderr || "") + (r.error ? String(r.error) : "") };
}

write("vitest.config.mjs", [
  "import { writeFileSync } from 'node:fs'",
  "export default {",
  "  test: {",
  "    reporters: ['default', {",
  "      onTestRunEnd(testModules) {",
  "        writeFileSync(new URL('./diag.json', import.meta.url), JSON.stringify(testModules.map(m => m.diagnostic().workerId)))",
  "      },",
  "    }],",
  "  },",
  "}",
].join("\n") + "\n");
write("one.test.mjs", [
  "import { test } from 'vitest'",
  "import { writeFileSync } from 'node:fs'",
  "test('records worker id', () => { writeFileSync(new URL('./env.txt', import.meta.url), String(process.env.VITEST_WORKER_ID)) })",
].join("\n") + "\n");
const r = vitest(["run"]);
console.log(r.out);
const envFile = path.join(dir, "env.txt");
const diagFile = path.join(dir, "diag.json");
if (!fs.existsSync(envFile) || !fs.existsSync(diagFile)) {
  console.error("ERROR: the test file or the reporter did not run (exit " + r.status + ")");
  process.exit(2);
}
const envId = fs.readFileSync(envFile, "utf8");
const diag = JSON.parse(fs.readFileSync(diagFile, "utf8"));
console.log("VITEST_WORKER_ID=" + envId + ", diagnostic().workerId=" + JSON.stringify(diag));
// The symptom of the old behavior: the first worker got id 0.
if (envId === "0") {
  console.error("FAIL: VITEST_WORKER_ID of the first worker was 0, not 1");
  process.exit(1);
}
if (r.status === 0 && envId === "1" && diag.length === 1 && diag[0] === 1) {
  console.log("PASS: the first worker has workerId 1");
  process.exit(0);
}
console.error("ERROR: unexpected result (VITEST_WORKER_ID=" + envId + ", diagnostic " + JSON.stringify(diag) + ", exit " + r.status + ")");
process.exit(2);

